#define OVERLAY_BANK_SIZE 0x1000

// Root Segment (Always Resident)
typedef struct {
    int config[4];
    void (*startup_hook)();
} SegmentRoot;

// Specific Tasks/Segments
typedef struct { char task_a_code[OVERLAY_BANK_SIZE]; } SegmentA;
typedef struct { float task_b_data[100]; } SegmentB;

// Shared Memory Region: A union defining the space overlays compete for
union OverlayRegion {
    SegmentA TaskA;
    SegmentB TaskB; // Task B occupies same physical address space as Task A
    char raw_bank[OVERLAY_BANK_SIZE];
};

// Program State Structure
struct OverlayProgram {
    SegmentRoot root;
    union OverlayRegion swap_space; // The active overlay resides here
    int current_overlay_id;
    void (*load_segment)(int id); // System function to swap memory content
};
